// ============================================================
// RAPOR TARİHİ AYARI
// Boş ('') bırakılırsa normal çalışır: gönderim günü = bugün (Europe/Istanbul),
// rapor günü = dün.
// 'YYYY-MM-DD' yazılırsa workflow o gün çalışıyormuş gibi davranır
// (örn. '2026-10-02' → 1 Ekim 2026 raporu üretilir).
// ============================================================
const RUN_DATE_OVERRIDE = '2026-10-02';

const pad = (n) => String(n).padStart(2, '0');
function addDaysStr(dateStr, days) {
  const parts = dateStr.split('-').map(Number);
  const dt = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2]));
  dt.setUTCDate(dt.getUTCDate() + days);
  return dt.getUTCFullYear() + '-' + pad(dt.getUTCMonth() + 1) + '-' + pad(dt.getUTCDate());
}

const todayIst = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Istanbul' });
const runDate  = /^\d{4}-\d{2}-\d{2}$/.test(RUN_DATE_OVERRIDE) ? RUN_DATE_OVERRIDE : todayIst;
const maxDay   = addDaysStr(runDate, -1);   // rapor günü ("dün")

return [{ json: {
  runDate,
  maxDay,
  startDay: addDaysStr(maxDay, -30),        // statistics sorgusunun alt sınırı
  isOverride: runDate !== todayIst,
} }];

const statRows     = $("statistics").all().map(i => i.json);
const infoRows     = $("info").all().map(i => i.json);
const lifetimeRows = $("lifetime").all().map(i => i.json).filter(r => r && r.advertisement_id != null);

// ============================================================
// SABİT CPM AYARI
// Tüm maliyet (spending) ve CPC değerleri bu CPM üzerinden
// yeniden hesaplanır. Farklı bir değer için sadece bu satırı değiştir.
// Formül: spending = views * FIXED_CPM / 1000
// ============================================================
const FIXED_CPM = 70; // ₺  (1000 gösterim başına maliyet)

const adInfoById = new Map(
  infoRows.map(r => [String(r.ad_id), {
    ad_name:       r.ad_name,
    campaign_id:   r.ca_id,
    campaign_name: r.cam_name,
  }])
);

const pad = (n) => String(n).padStart(2, '0');
function dayStrOf(r) {
  const raw = r.day;
  if (typeof raw === 'string') return raw.slice(0, 10);
  if (raw instanceof Date) {
    return raw.getUTCFullYear() + '-' + pad(raw.getUTCMonth() + 1) + '-' + pad(raw.getUTCDate());
  }
  return String(raw).slice(0, 10);
}
function addDaysStr(dateStr, days) {
  const parts = dateStr.split('-').map(Number);
  const dt = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2]));
  dt.setUTCDate(dt.getUTCDate() + days);
  return dt.getUTCFullYear() + '-' + pad(dt.getUTCMonth() + 1) + '-' + pad(dt.getUTCDate());
}

// ---- Sabit CPM'e göre maliyet hesabı ----
function spendFromViews(views) {
  return (Number(views) || 0) * FIXED_CPM / 1000;
}

// ---- Anchor: rapor günü ("dün"), config node'undan ----
const maxDay   = $("config").first().json.maxDay;
const cutoff7  = addDaysStr(maxDay, -6);
const cutoff30 = addDaysStr(maxDay, -29);

// ---- Kampanya bazında toplamlar ----
// Her kampanya için: dün / son 7 gün / son 30 gün / tüm zamanlar
const campaigns = new Map();
function campaignOf(adId, fallbackCampaignId) {
  const info = adInfoById.get(String(adId)) || {};
  const id   = info.campaign_id ?? fallbackCampaignId ?? null;
  const key  = String(id);
  if (!campaigns.has(key)) {
    campaigns.set(key, {
      campaign_id:   id,
      campaign_name: info.campaign_name || null,
      views_1d: 0,  clicks_1d: 0,  spend_1d: 0,
      views_7d: 0,  clicks_7d: 0,  spend_7d: 0,
      views_30d: 0, clicks_30d: 0, spend_30d: 0,
      views_total: 0, clicks_total: 0, spend_total: 0,
    });
  }
  const c = campaigns.get(key);
  if (!c.campaign_name && info.campaign_name) c.campaign_name = info.campaign_name;
  return c;
}

// ---- Global 7d / 30d toplamları (tüm statRows, dün filtresiz) ----
// Maliyet sabit CPM üzerinden: spending = views * FIXED_CPM / 1000
let sum7  = { views: 0, clicks: 0, spending: 0 };
let sum30 = { views: 0, clicks: 0, spending: 0 };

for (const r of statRows) {
  const d = dayStrOf(r);
  const v = Number(r.views    ?? 0);
  const c = Number(r.clicks   ?? 0);
  const s = spendFromViews(v);            // <-- sabit CPM'e göre yeniden hesaplandı
  if (d >= cutoff30 && d <= maxDay) {
    const cam = campaignOf(r.advertisement_id, r.campaign_id);
    sum30.views += v; sum30.clicks += c; sum30.spending += s;
    cam.views_30d += v; cam.clicks_30d += c; cam.spend_30d += s;
    if (d >= cutoff7) {
      sum7.views += v; sum7.clicks += c; sum7.spending += s;
      cam.views_7d += v; cam.clicks_7d += c; cam.spend_7d += s;
    }
    if (d === maxDay) {
      cam.views_1d += v; cam.clicks_1d += c; cam.spend_1d += s;
    }
  }
}

// ---- Tüm zamanlar (lifetime node'undan, reklam bazında) ----
let sumAll = { views: 0, clicks: 0, spending: 0 };
for (const r of lifetimeRows) {
  const v = Number(r.views  ?? 0);
  const c = Number(r.clicks ?? 0);
  const s = spendFromViews(v);
  sumAll.views += v; sumAll.clicks += c; sumAll.spending += s;
  const cam = campaignOf(r.advertisement_id, r.campaign_id);
  cam.views_total += v; cam.clicks_total += c; cam.spend_total += s;
}

// ---- Per-ad (dün) satırları ----
const byAd = new Map();
for (const r of statRows) {
  if (!byAd.has(r.advertisement_id)) byAd.set(r.advertisement_id, []);
  byAd.get(r.advertisement_id).push(r);
}

const output = [];
for (const [adId, rows] of byAd) {
  const info  = adInfoById.get(String(adId)) || {};
  const daily = rows.find(r => dayStrOf(r) === maxDay);
  if (!daily) continue; // dün verisi olmayan reklamlar tabloya girmez

  const dViews  = Number(daily.views)  || 0;
  const dClicks = Number(daily.clicks) || 0;
  const dSpend  = spendFromViews(dViews);            // <-- sabit CPM'e göre maliyet

  output.push({
    advertisement_id:   adId,
    advertisement_name: info.ad_name       || null,
    campaign_id:        info.campaign_id   ?? daily.campaign_id ?? null,
    campaign_name:      info.campaign_name || null,
    day:      dayStrOf(daily),
    views:    dViews,
    clicks:   dClicks,
    spending: dSpend,                                          // <-- yeniden hesaplandı
    cpm: dViews  > 0 ? FIXED_CPM : null,                       // <-- sabit CPM
    cpc: dClicks > 0 ? dSpend / dClicks : null,                // <-- yeniden hesaplandı
    ctr: daily.ctr != null ? Number(daily.ctr) : null,         // CTR maliyetten etkilenmez, aynen kalır
  });
}

// ---- Kampanya özet satırları (period: 'campaign') ----
// Sadece son 30 günde gösterimi olan (aktif) kampanyalar rapora girer.
const campaignList = [...campaigns.values()]
  .filter(c => c.views_30d > 0)
  .sort((a, b) => String(a.campaign_name ?? a.campaign_id)
    .localeCompare(String(b.campaign_name ?? b.campaign_id), 'tr'));

for (const c of campaignList) {
  output.push({
    advertisement_id: null,
    advertisement_name: null,
    period: 'campaign',
    day: null,
    ...c,
  });
}

// ---- Özet satırlar (day: null) ----
output.push({
  advertisement_id: null,
  advertisement_name: null,
  campaign_id: null,
  campaign_name: null,
  period:   '7d',
  day:      null,
  views:    sum7.views,
  clicks:   sum7.clicks,
  spending: sum7.spending,
});
output.push({
  advertisement_id: null,
  advertisement_name: null,
  campaign_id: null,
  campaign_name: null,
  period:   '30d',
  day:      null,
  views:    sum30.views,
  clicks:   sum30.clicks,
  spending: sum30.spending,
});
output.push({
  advertisement_id: null,
  advertisement_name: null,
  campaign_id: null,
  campaign_name: null,
  period:   'all',
  day:      null,
  views:    sumAll.views,
  clicks:   sumAll.clicks,
  spending: sumAll.spending,
});

return output.map(json => ({ json }));

// =====================================================
// n8n Code Node — MagfiADS Günlük Özet E-posta HTML
// =====================================================
// Görseller — Magfi CDN
const IMG_LOGO     = 'https://gcdn.magfiads.com/assets/static/icons/Page-1.png';
const IMG_LINKEDIN = 'https://gcdn.magfiads.com/assets/static/icons/linkedin.png';
const IMG_TELEGRAM = 'https://gcdn.magfiads.com/assets/static/icons/telegram.png';
const IMG_MEDIUM   = 'https://gcdn.magfiads.com/assets/static/icons/medium.png';

// ---- Tüm girdileri al ----
const allInputs = $input.all().map(i => i.json).filter(Boolean);

// Per-ad (dün) satırları — tabloyu ve günlük toplamları bunlar doldurur
const ads = allInputs.filter(r => r.advertisement_id != null);
const dailyAds = ads;

// Kampanya bazında özet satırları (merge node'undan, period: 'campaign')
const campaignSummaries = allInputs.filter(r => r.advertisement_id == null && r.period === 'campaign');

// ---- Rapor tarihi (ads[0].day zaten "YYYY-MM-DD" = dün) ----
const reportDateStr = ads[0]?.day;
const reportDate = reportDateStr
  ? new Date(reportDateStr + 'T00:00:00Z')
  : (() => { const d = new Date(); d.setDate(d.getDate() - 1); return d; })();
const dateStr = reportDate.toLocaleDateString('tr-TR', {
  year: 'numeric', month: 'long', day: 'numeric'
});
const now = new Date().toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul' });

// ---- Formatlar ----
const formatMoney = (val) =>
  new Intl.NumberFormat('tr-TR', {
    style: 'currency', currency: 'TRY', minimumFractionDigits: 2
  }).format(Number(val) || 0);
const formatNumber  = (val) => new Intl.NumberFormat('tr-TR').format(Number(val) || 0);
const formatPercent = (val) => '%' + (Number(val) || 0).toFixed(2);
const esc = (val) => String(val ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

// ---- Günlük toplamlar (dün) ----
let totalSpend = 0, totalClicks = 0, totalViews = 0;
ads.forEach(a => {
  totalSpend  += Number(a.spending) || 0;
  totalClicks += Number(a.clicks)   || 0;
  totalViews  += Number(a.views)    || 0;
});
// ---- Görüntülenme 0 ise maili gönderme (workflow burada durur) ----
if (totalViews === 0) {
  return [];
}
const totalCpm = totalViews  > 0 ? (totalSpend / totalViews * 1000) : 0;
const totalCpc = totalClicks > 0 ? (totalSpend / totalClicks)       : 0;
const totalCtr = totalViews  > 0 ? (totalClicks / totalViews * 100) : 0;

// ---- 7 gün / 30 gün / tüm zamanlar (merge'ün day:null özet satırlarından) ----
const summary7d  = allInputs.find(r => r.advertisement_id == null && r.period === '7d')  || {};
const summary30d = allInputs.find(r => r.advertisement_id == null && r.period === '30d') || {};
const summaryAll = allInputs.find(r => r.advertisement_id == null && r.period === 'all') || {};
const spend7d   = Number(summary7d.spending)  || 0;
const spend30d  = Number(summary30d.spending) || 0;
const spendAll  = Number(summaryAll.spending) || 0;

// ---- Kampanya bazında harcama kartları (her satırda en fazla 3 kart) ----
const campaignCard = (c) => {
  const camName = esc(c.campaign_name || c.campaign_id);
  const line = (label, value, bold) => `
                          <tr>
                            <td style="padding:4px 0; font-family:Inter,Arial,sans-serif; font-size:12px; color:#475467;">${label}</td>
                            <td style="padding:4px 0; font-family:Inter,Arial,sans-serif; font-size:12px; font-weight:${bold ? 700 : 600}; color:#0C111D; text-align:right; white-space:nowrap;">${value}</td>
                          </tr>`;
  return `
                    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#FFFFFF; border:1px solid #EAECF0; border-radius:16px;">
                      <tr><td style="padding:18px 16px;">
                        <p style="margin:0 0 12px; font-family:Inter,Arial,sans-serif; font-size:13px; font-weight:600; color:#6941C6; line-height:18px;">${camName}</p>
                        <p style="margin:0 0 4px; font-family:Inter,Arial,sans-serif; font-size:11px; font-weight:600; color:#475467; text-transform:uppercase; letter-spacing:0.5px;">D&#252;nk&#252; Harcama</p>
                        <p style="margin:0 0 4px; font-family:Inter,Arial,sans-serif; font-size:20px; font-weight:700; color:#0C111D;">${formatMoney(c.spend_1d)}</p>
                        <p style="margin:0 0 12px; font-family:Inter,Arial,sans-serif; font-size:11px; color:#475467;">${formatNumber(c.views_1d)} g&#246;r&#252;nt&#252;lenme &#183; ${formatNumber(c.clicks_1d)} t&#305;klama</p>
                        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #EAECF0;">
                          <tr><td colspan="2" style="font-size:0; line-height:0; padding-top:6px;">&#160;</td></tr>${line('Son 7 G&#252;n', formatMoney(c.spend_7d))}${line('Son 30 G&#252;n', formatMoney(c.spend_30d))}${line('Toplam Harcama', formatMoney(c.spend_total), true)}
                        </table>
                      </td></tr>
                    </table>`;
};

let campaignCardsHtml = '';
if (campaignSummaries.length > 0) {
  const perRow = Math.min(3, campaignSummaries.length);
  const cellWidth = Math.floor(100 / perRow) + '%';
  for (let i = 0; i < campaignSummaries.length; i += perRow) {
    const chunk = campaignSummaries.slice(i, i + perRow);
    let cells = '';
    for (let j = 0; j < perRow; j++) {
      const padding = perRow === 1 ? '0' : j === 0 ? '0 4px 0 0' : j === perRow - 1 ? '0 0 0 4px' : '0 4px';
      cells += `
                  <td width="${cellWidth}" valign="top" style="padding:${padding};">${chunk[j] ? campaignCard(chunk[j]) : '&#160;'}</td>`;
    }
    campaignCardsHtml += `
          <tr>
            <td style="padding:0 32px ${i + perRow >= campaignSummaries.length ? 28 : 8}px;">
              <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
                <tr>${cells}
                </tr>
              </table>
            </td>
          </tr>`;
  }
  campaignCardsHtml = `
          <tr>
            <td style="padding:0 32px 16px;">
              <p style="margin:0; font-family:Inter,Arial,sans-serif; font-size:16px; font-weight:600; color:#0C111D;">Kampanya Baz&#305;nda Harcama</p>
            </td>
          </tr>` + campaignCardsHtml;
}

// ---- Kampanya tablo satırları (kampanyaya göre gruplu + ara toplamlar) ----
const cell = (content, opts = {}) =>
  `<td${opts.colspan ? ` colspan="${opts.colspan}"` : ''} style="padding:10px 8px; font-family:Inter,Arial,sans-serif; font-size:${opts.size || 11}px;${opts.weight ? ` font-weight:${opts.weight};` : ''} color:${opts.color || '#475467'};${opts.left ? '' : ' text-align:right;'} border-bottom:1px solid #EAECF0;${opts.left ? '' : ' white-space:nowrap;'}">${content}</td>`;

const metricCells = (spend, views, clicks, weight) => {
  const cpm = views  > 0 ? spend / views * 1000  : 0;
  const cpc = clicks > 0 ? spend / clicks        : 0;
  const ctr = views  > 0 ? clicks / views * 100  : 0;
  return [
    cell(formatMoney(spend),  { weight: 700, color: '#101828' }),
    cell(formatNumber(views), { weight }),
    cell(formatNumber(clicks),{ weight }),
    cell(formatMoney(cpm),    { weight }),
    cell(formatMoney(cpc),    { weight }),
    cell(formatPercent(ctr),  { weight }),
  ].join('\n    ');
};

const groups = new Map();
dailyAds.forEach(a => {
  const key = String(a.campaign_id);
  if (!groups.has(key)) groups.set(key, { name: a.campaign_name || a.campaign_id, ads: [] });
  groups.get(key).ads.push(a);
});
const sortedGroups = [...groups.values()]
  .sort((x, y) => String(x.name).localeCompare(String(y.name), 'tr'));

let campaignRows = '';
sortedGroups.forEach(g => {
  let gSpend = 0, gViews = 0, gClicks = 0;
  g.ads
    .sort((x, y) => String(x.advertisement_name ?? x.advertisement_id)
      .localeCompare(String(y.advertisement_name ?? y.advertisement_id), 'tr'))
    .forEach((a, i) => {
      gSpend  += Number(a.spending) || 0;
      gViews  += Number(a.views)    || 0;
      gClicks += Number(a.clicks)   || 0;
      const bg = i % 2 === 0 ? '#FFFFFF' : '#F9FAFB';
      campaignRows += `
    <tr style="background-color:${bg};">
      ${cell(esc(g.name), { left: true, size: 12, weight: 500, color: '#101828' })}
      ${cell(esc(a.advertisement_name || a.advertisement_id), { left: true, size: 12 })}
      ${cell(formatMoney(a.spending), { weight: 600, color: '#101828' })}
      ${cell(formatNumber(a.views))}
      ${cell(formatNumber(a.clicks))}
      ${cell(formatMoney(a.cpm))}
      ${cell(formatMoney(a.cpc))}
      ${cell(formatPercent(a.ctr))}
    </tr>`;
    });
  // Kampanya ara toplamı
  campaignRows += `
  <tr style="background-color:#F4F3FF;">
    ${cell(esc(g.name) + ' Toplam&#305;', { colspan: 2, left: true, size: 12, weight: 700, color: '#6941C6' })}
    ${metricCells(gSpend, gViews, gClicks, 600)}
  </tr>`;
});

// Genel toplam satırı
campaignRows += `
  <tr style="background-color:#F2F4F7;">
    ${cell('Genel Toplam', { colspan: 2, left: true, size: 12, weight: 700, color: '#101828' })}
    ${metricCells(totalSpend, totalViews, totalClicks, 600)}
  </tr>`;

// ---- HTML (tasarım aynı) ----
const html = `<!DOCTYPE html>
<html lang="tr">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
</head>
<body style="margin:0; padding:0; background-color:#FFFFFF; font-family:Inter,Arial,Helvetica,sans-serif; -webkit-font-smoothing:antialiased;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#FFFFFF; padding:32px 0;">
    <tr>
      <td align="center">

        <table role="presentation" width="750" cellpadding="0" cellspacing="0" style="margin-bottom:24px;">
          <tr>
            <td align="center" style="padding-bottom:16px;">
              <img src="${IMG_LOGO}" alt="MagfiADS" width="180" style="display:block; border:0; outline:none;">
            </td>
          </tr>
          <tr>
            <td align="center" style="padding-bottom:20px;">
              <table role="presentation" cellpadding="0" cellspacing="0">
                <tr>
                  <td style="background-color:#D1E9FF; border-radius:16px; padding:4px 14px;">
                    <span style="font-family:Inter,Arial,sans-serif; font-size:14px; font-weight:500; color:#175CD3;">G&#252;nl&#252;k &#214;zet</span>
                  </td>
                </tr>
              </table>
            </td>
          </tr>
        </table>

        <table role="presentation" width="750" cellpadding="0" cellspacing="0" style="background-color:#FCFCFD; border:1px solid #EAECF0; border-radius:6px;">
          <tr>
            <td style="padding:32px 32px 8px;">
              <p style="margin:0; font-family:Inter,Arial,sans-serif; font-size:18px; font-weight:600; color:#0C111D; line-height:28px;">Merhaba,</p>
            </td>
          </tr>
          <tr>
            <td style="padding:0 32px 28px;">
              <p style="margin:0; font-family:Inter,Arial,sans-serif; font-size:14px; font-weight:400; color:#475467; line-height:22px;">
                ${dateStr} tarihine ait reklam performans &#246;zetiniz a&#351;a&#287;&#305;dad&#305;r.
              </p>
            </td>
          </tr>
          <tr>
            <td style="padding:0 32px 16px;">
              <p style="margin:0; font-family:Inter,Arial,sans-serif; font-size:16px; font-weight:600; color:#0C111D;">Temel Metrikler</p>
            </td>
          </tr>

          <tr>
            <td style="padding:0 32px 8px;">
              <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
                <tr>
                  <td width="33%" style="padding:0 4px 0 0;">
                    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#F9FAFB; border:1px solid #EAECF0; border-radius:16px;">
                      <tr><td style="padding:20px 16px;">
                        <p style="margin:0 0 8px; font-family:Inter,Arial,sans-serif; font-size:12px; font-weight:500; color:#6941C6; text-transform:uppercase; letter-spacing:0.5px;">Toplam Harcama</p>
                        <p style="margin:0; font-family:Inter,Arial,sans-serif; font-size:22px; font-weight:700; color:#0C111D;">${formatMoney(totalSpend)}</p>
                      </td></tr>
                    </table>
                  </td>
                  <td width="33%" style="padding:0 4px;">
                    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#F9FAFB; border:1px solid #EAECF0; border-radius:16px;">
                      <tr><td style="padding:20px 16px;">
                        <p style="margin:0 0 8px; font-family:Inter,Arial,sans-serif; font-size:12px; font-weight:500; color:#6941C6; text-transform:uppercase; letter-spacing:0.5px;">G&#246;r&#252;nt&#252;lenme</p>
                        <p style="margin:0; font-family:Inter,Arial,sans-serif; font-size:22px; font-weight:700; color:#0C111D;">${formatNumber(totalViews)}</p>
                      </td></tr>
                    </table>
                  </td>
                  <td width="33%" style="padding:0 0 0 4px;">
                    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#F9FAFB; border:1px solid #EAECF0; border-radius:16px;">
                      <tr><td style="padding:20px 16px;">
                        <p style="margin:0 0 8px; font-family:Inter,Arial,sans-serif; font-size:12px; font-weight:500; color:#6941C6; text-transform:uppercase; letter-spacing:0.5px;">T&#305;klama</p>
                        <p style="margin:0; font-family:Inter,Arial,sans-serif; font-size:22px; font-weight:700; color:#0C111D;">${formatNumber(totalClicks)}</p>
                      </td></tr>
                    </table>
                  </td>
                </tr>
              </table>
